<div class="store-wrap blade-page" x-data="accountPreview"><h1>Mis direcciones</h1><x-account-nav /><section class="blade-panel"><h2 class="text-xl font-bold">Dirección de ejemplo</h2><address class="not-italic my-4">Casa · Explorador de muestra<br>Sendero 123, Colonia Centro<br>Ciudad de México, 06000 · MX</address><p class="page-note">Dirección ficticia. No se lee ni se guarda información personal.</p><button class="store-button primary mt-4" @click="$refs.address.showModal()" type="button">Revisar formulario</button><p class="blade-status" x-show="feedback" x-text="feedback" role="status" x-cloak></p></section><dialog class="blade-dialog" x-ref="address" aria-labelledby="address-title"><h2 class="text-xl font-bold mb-4" id="address-title">Dirección · Vista previa</h2><form class="blade-form" @submit.prevent="feedback = 'Formulario validado. No se guardó ninguna dirección.'; $refs.address.close()"><label>Destinatario<input required autocomplete="shipping name"></label><label>Calle y número<input required autocomplete="shipping address-line1"></label><label>Ciudad<input required autocomplete="shipping address-level2"></label><label>Estado<input required autocomplete="shipping address-level1"></label><label>Código postal<input required pattern="[0-9]{5}" maxlength="5" autocomplete="shipping postal-code"></label><div class="blade-actions"><button class="store-button primary" type="submit">Validar ejemplo</button><button class="store-button" type="button" @click="$refs.address.close()">Cancelar</button></div></form></dialog></div>
